head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40401";
scwin.sub_apctDd_Y = null;
scwin.sub_apctDd_M = null;
scwin.sub_apctDd_D = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — corpUsrTpCd, rexName

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil40401.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_8", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '11'); } }, { id: "c_when_10", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21'); } }, { id: "c_when_12", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '61'); } }, { id: "c_when_14", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '12'); } }, { id: "c_when_16", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '16' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '17'); } }, { id: "c_when_18", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1F' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1G'); } }, { id: "c_when_20", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19'); } }, { id: "c_when_22", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1A' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1B'); } }, { id: "c_when_24", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '22'); } }, { id: "c_when_26", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '31'); } }, { id: "c_when_28", fn: function(){ return ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1C' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1D' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1E'); } }, { id: "c_otherwise_30", fn: function(){ return (!(((dma_pageContext.get("corpUsrTpCd") ?? "") === '11') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '21') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '61') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '12') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '16' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '17') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1F' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1G') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '19') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1A' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1B') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '22') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '31') || ((dma_pageContext.get("corpUsrTpCd") ?? "") === '1C' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1D' || (dma_pageContext.get("corpUsrTpCd") ?? "") === '1E'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "담당자의 확인 후 최종 임시비밀번호와 비밀번호변경코드를 E-Mail(" + String(String((dma_pageContext.get("apctEmail") ?? ""))) + ")로 보내드립니다."; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Print_onclick
 * @description btn_Print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Print_onclick = function(e){
    try {
        scwin.print('' + dma_pageContext.get("apctId") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40401.btn_Print_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_Print
 * @description Print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_PrintReq") ? $c.util.getComponent("dma_PrintReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name print
 * @description print 처리
 * @param {String} _apctId _apctId
 * @returns {void}
 * @hidden N
 */
scwin.print = function (_apctId) {
    const rexName = (String(((dma_pageContext.get("rexName") ?? "")) == null ? '' : ((dma_pageContext.get("rexName") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("rexName") ?? "")) == null ? '' : ((dma_pageContext.get("rexName") ?? ""))));
    if (rexName === '') {
        return;
    }
    const dataLocation = "/outer/reportPrint.do?method=passwordReissuanceNewReport&apctId=" + _apctId;
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_PrintReq').set('nisurCd', result.isurCd);
                $c.util.getComponent('dma_PrintReq').set('ncorpNm', result.corpNm);
                $c.util.getComponent('dma_PrintReq').set('ncorpRegNo', result.corpRegNo);
                $c.util.getComponent('dma_PrintReq').set('nbzRegNo', result.bzRegNo);
                $c.util.getComponent('dma_PrintReq').set('nrepNm', result.repNm);
                $c.util.getComponent('dma_PrintReq').set('nhpage', result.hpage);
                $c.util.getComponent('dma_PrintReq').set('nlocAddr', result.locAddr);
                $c.util.getComponent('dma_PrintReq').set('nlocZipcd', result.locZipcd);
                $c.util.getComponent('dma_PrintReq').set('napctNm', result.apctNm);
                $c.util.getComponent('dma_PrintReq').set('napctTelNo', result.apctTelNo);
                $c.util.getComponent('dma_PrintReq').set('napctFaxNo', result.apctFaxNo);
                $c.util.getComponent('dma_PrintReq').set('napctEmail', result.apctEmail);
                $c.util.getComponent('dma_PrintReq').set('nreisuRsn', result.reisuRsn);
                $c.util.getComponent('dma_PrintReq').set('nTempleteCd', rexName);
                if (result.apctDd) {
                    const sub_apctDd = result.apctDd;
                    scwin.sub_apctDd_Y = sub_apctDd.substring(0, 4);
                    scwin.sub_apctDd_M = sub_apctDd.substring(4, 6);
                    scwin.sub_apctDd_D = sub_apctDd.substring(6, 8);
                    $c.util.getComponent('dma_PrintReq').set('napctDd', scwin.sub_apctDd_Y + "년 " + scwin.sub_apctDd_M + "월 " + scwin.sub_apctDd_D + "일");
                } else {
                    $c.util.getComponent('dma_PrintReq').set('napctDd', result.apctDd);
                }
                await scwin.tx_fn_Print();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};
